/**
 * @internal
 * Extension interface to extend the types of the columnDefinition from the tanstack table.
 */
export interface DataTableV2AlignmentColumnDef {
  /* Defines the text alignment inside the column cell */
  alignment?:
    | 'left'
    | 'center'
    | 'right'
    | 'top-left'
    | 'top-center'
    | 'top-right'
    | 'bottom-left'
    | 'bottom-center'
    | 'bottom-right';
}

export const DATA_TABLE_V2_DEFAULT_CELL_ALIGNMENT = 'left';
export const DATA_TABLE_V2_DEFAULT_HEADER_ALIGNMENT = 'top-left';
